const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define coastal regions of Victoria and New South Wales
  // Approximate bounding boxes
  const vicNswCoast = ee.Geometry.Polygon([
    [[141.0, -39.5], [141.0, -28.0], [154.0, -28.0], [154.0, -39.5], [141.0, -39.5]]
  ]);

  // Date 1: January 1, 2020 (Australian bushfire season)
  const date1Start = '2020-01-01';
  const date1End = '2020-01-02';

  // Date 2: July 24, 2019 (Australian winter)
  const date2Start = '2019-07-24';
  const date2End = '2019-07-25';

  // Try MODIS AOD (Aerosol Optical Depth) - direct smoke proxy
  const modisCol = ee.ImageCollection('MODIS/006/MOD08_M3');

  let col1 = modisCol.filterDate(date1Start, date1End)
    .filterBounds(vicNswCoast)
    .select('Optical_Depth_Land_And_Ocean');

  let col2 = modisCol.filterDate(date2Start, date2End)
    .filterBounds(vicNswCoast)
    .select('Optical_Depth_Land_And_Ocean');

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  if (size1 === 0 || size2 === 0) {
    // Fallback: Try Sentinel-5P CO (carbon monoxide proxy for smoke)
    const s5pCol = ee.ImageCollection('COPERNICUS/S5P/NRTI_CO');

    col1 = s5pCol.filterDate(date1Start, date1End)
      .filterBounds(vicNswCoast)
      .select('CO');

    col2 = s5pCol.filterDate(date2Start, date2End)
      .filterBounds(vicNswCoast)
      .select('CO');

    const s5pSize1 = col1.size().getInfo();
    const s5pSize2 = col2.size().getInfo();

    if (s5pSize1 === 0 || s5pSize2 === 0) {
      console.log(`MODIS: ${size1}, ${size2} | Sentinel-5P: ${s5pSize1}, ${s5pSize2}`);
      console.log("C1");
      return;
    }
  }

  console.log(`Jan 1 2020 Images: ${size1}, Jul 24 2019 Images: ${size2}`);

  // Compute mean AOD/CO for each date
  const img1 = col1.first();
  const img2 = col2.first();

  if (img1 === null || img2 === null) {
    console.log("C1");
    return;
  }

  const bandName = img1.bandNames().getInfo()[0] || 'Optical_Depth_Land_And_Ocean';

  // Get mean values
  const stats1 = img1.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: vicNswCoast,
    scale: 1000,
    maxPixels: 1e9
  });

  const stats2 = img2.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: vicNswCoast,
    scale: 1000,
    maxPixels: 1e9
  });

  const val1 = stats1.getInfo()[bandName];
  const val2 = stats2.getInfo()[bandName];

  // Check for valid pixels
  const count1 = img1.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: vicNswCoast,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo()[bandName] || 0;

  const count2 = img2.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: vicNswCoast,
    scale: 1000,
    maxPixels: 1e9
  }).getInfo()[bandName] || 0;

  console.log(`Jan 1 2020 AOD: ${val1}, Pixels: ${count1}`);
  console.log(`Jul 24 2019 AOD: ${val2}, Pixels: ${count2}`);

  if (count1 === 0 || count2 === 0) {
    console.log("C2");
    return;
  }

  if (val1 === null || val1 === undefined || val2 === null || val2 === undefined || 
      isNaN(val1) || isNaN(val2)) {
    console.log("C3");
    return;
  }

  // Compare smoke levels
  if (val1 > val2) {
    console.log(`More smoke on Jan 1 2020 (${val1.toFixed(3)}) vs Jul 24 2019 (${val2.toFixed(3)})`);
    console.log("A");
  } else {
    console.log(`Less or equal smoke on Jan 1 2020 (${val1.toFixed(3)}) vs Jul 24 2019 (${val2.toFixed(3)})`);
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
